from flask import Flask, jsonify, request
from datetime import datetime
from uuid import uuid4

app = Flask(__name__)

state = {
    "catalog_ready": False,
    "products": {},
    "orders": {},
    "audit": [],
    "carts": {},
}

VALID_STATUSES = ["pending", "review", "approved", "rejected", "fulfillment", "shipped", "canceled"]
ALLOWED_TRANSITIONS = {
    "pending": {"review", "approved", "rejected", "canceled"},
    "review": {"approved", "rejected", "pending", "canceled"},
    "approved": {"fulfillment", "shipped", "canceled"},
    "rejected": set(),
    "fulfillment": {"shipped", "canceled"},
    "shipped": set(),
    "canceled": set(),
}


def now():
    return datetime.utcnow().isoformat() + "Z"


def audit(action, actor, before, after):
    state["audit"].append({
        "id": str(uuid4()),
        "time": now(),
        "actor": actor,
        "action": action,
        "before": before,
        "after": after,
    })


def product_purchasable(product):
    if not product.get("active", True):
        return False, "Product is inactive"
    if not product.get("price") or product.get("price", 0) <= 0:
        return False, "Product price is missing or invalid"
    if product.get("stock_control", True) and product.get("stock", 0) <= 0:
        return False, "Product is out of stock"
    if not state["catalog_ready"]:
        return False, "Catalog is not yet ready"
    return True, ""


def validate_product(payload):
    required = ["name", "price"]
    for key in required:
        if key not in payload or payload[key] in [None, ""]:
            return f"Missing required field: {key}"
    if not isinstance(payload["price"], (int, float)) or payload["price"] <= 0:
        return "Price must be a positive number"
    if "stock" in payload and (not isinstance(payload["stock"], int) or payload["stock"] < 0):
        return "Stock must be a non-negative integer"
    return None


@app.get("/")
def home():
    return jsonify({"message": "GAMMA-J Web Store", "catalog_ready": state["catalog_ready"]})


@app.get("/products")
def list_products():
    products = []
    for product in state["products"].values():
        purchasable, reason = product_purchasable(product)
        p = dict(product)
        p["purchasable"] = purchasable
        if not purchasable:
            p["unavailable_reason"] = reason
        products.append(p)
    return jsonify(products)


@app.post("/admin/catalog/ready")
def set_catalog_ready():
    data = request.get_json(force=True, silent=True) or {}
    ready = bool(data.get("ready", True))
    before = {"catalog_ready": state["catalog_ready"]}
    state["catalog_ready"] = ready
    audit("catalog_ready", data.get("actor", "system"), before, {"catalog_ready": ready})
    return jsonify({"catalog_ready": ready})


@app.post("/admin/products")
def create_product():
    data = request.get_json(force=True, silent=True) or {}
    err = validate_product(data)
    if err:
        return jsonify({"error": err}), 400
    pid = str(uuid4())
    product = {
        "id": pid,
        "name": data["name"],
        "description": data.get("description", ""),
        "price": float(data["price"]),
        "stock": int(data.get("stock", 0)),
        "active": bool(data.get("active", True)),
        "stock_control": bool(data.get("stock_control", True)),
        "category": data.get("category", "Uncategorized"),
        "images": data.get("images", []),
        "min_qty": int(data.get("min_qty", 1)),
        "max_qty": data.get("max_qty"),
    }
    state["products"][pid] = product
    audit("create_product", data.get("actor", "staff"), None, product)
    return jsonify(product), 201


@app.put("/admin/products/<pid>")
def update_product(pid):
    if pid not in state["products"]:
        return jsonify({"error": "Product not found"}), 404
    data = request.get_json(force=True, silent=True) or {}
    before = dict(state["products"][pid])
    product = state["products"][pid]
    for k in ["name", "description", "category"]:
        if k in data:
            product[k] = data[k]
    if "price" in data:
        if not isinstance(data["price"], (int, float)) or data["price"] <= 0:
            return jsonify({"error": "Price must be a positive number"}), 400
        product["price"] = float(data["price"])
    if "stock" in data:
        if not isinstance(data["stock"], int) or data["stock"] < 0:
            return jsonify({"error": "Stock must be a non-negative integer"}), 400
        product["stock"] = data["stock"]
    if "active" in data:
        product["active"] = bool(data["active"])
    if "stock_control" in data:
        product["stock_control"] = bool(data["stock_control"])
    if "images" in data:
        product["images"] = data["images"]
    after = dict(product)
    audit("update_product", data.get("actor", "staff"), before, after)
    return jsonify(product)


@app.post("/cart/<customer_id>/items")
def add_to_cart(customer_id):
    data = request.get_json(force=True, silent=True) or {}
    pid = data.get("product_id")
    qty = int(data.get("quantity", 1))
    if qty <= 0:
        return jsonify({"error": "Quantity must be positive"}), 400
    product = state["products"].get(pid)
    if not product:
        return jsonify({"error": "Product not found"}), 404
    purchasable, reason = product_purchasable(product)
    if not purchasable:
        return jsonify({"error": reason}), 400
    cart = state["carts"].setdefault(customer_id, {})
    cart[pid] = cart.get(pid, 0) + qty
    max_qty = product.get("max_qty")
    if max_qty is not None and cart[pid] > max_qty:
        cart[pid] -= qty
        return jsonify({"error": f"Cart exceeds max quantity for {product['name']}"}), 400
    return jsonify({"customer_id": customer_id, "items": cart})


@app.get("/cart/<customer_id>")
def get_cart(customer_id):
    cart = state["carts"].get(customer_id, {})
    items = []
    total = 0.0
    for pid, qty in cart.items():
        product = state["products"].get(pid)
        if not product:
            continue
        line = product["price"] * qty
        total += line
        items.append({"product_id": pid, "name": product["name"], "quantity": qty, "price": product["price"], "line_total": line})
    return jsonify({"customer_id": customer_id, "items": items, "total": total})


@app.post("/checkout/<customer_id>")
def checkout(customer_id):
    cart = state["carts"].get(customer_id, {})
    if not cart:
        return jsonify({"error": "Cart is empty"}), 400
    address = (request.get_json(force=True, silent=True) or {}).get("shipping_address", {})
    for field in ["street", "city", "postal_code", "country"]:
        if not address.get(field):
            return jsonify({"error": f"Shipping address missing {field}"}), 400
    items = []
    total = 0.0
    for pid, qty in cart.items():
        product = state["products"].get(pid)
        if not product:
            return jsonify({"error": "Product missing from catalog"}), 400
        purchasable, reason = product_purchasable(product)
        if not purchasable:
            return jsonify({"error": reason}), 400
        if product.get("stock_control", True) and product["stock"] < qty:
            return jsonify({"error": f"Insufficient stock for {product['name']}"}), 400
        items.append({"product_id": pid, "name": product["name"], "quantity": qty, "price": product["price"]})
        total += product["price"] * qty
    order_id = str(uuid4())
    order = {"id": order_id, "customer_id": customer_id, "items": items, "total": total, "status": "pending", "payment_status": "unpaid", "shipping_address": address, "created_at": now()}
    state["orders"][order_id] = order
    state["carts"][customer_id] = {}
    return jsonify(order), 201


@app.get("/orders/<order_id>")
def get_order(order_id):
    order = state["orders"].get(order_id)
    if not order:
        return jsonify({"error": "Order not found"}), 404
    return jsonify(order)


@app.post("/orders/<order_id>/pay")
def pay_order(order_id):
    order = state["orders"].get(order_id)
    if not order:
        return jsonify({"error": "Order not found"}), 404
    data = request.get_json(force=True, silent=True) or {}
    method = data.get("payment_method", "trusted_provider")
    if data.get("simulate_failure"):
        order["payment_status"] = "failed"
        order["status"] = "pending"
        return jsonify({"status": "failure", "message": "Payment failed. You can retry or choose another method.", "payment_method": method}), 402
    order["payment_status"] = "paid"
    order["status"] = "approved"
    return jsonify({"status": "success", "message": "Payment accepted and order confirmed.", "order_id": order_id, "payment_method": method})


@app.post("/orders/<order_id>/status")
def change_status(order_id):
    order = state["orders"].get(order_id)
    if not order:
        return jsonify({"error": "Order not found"}), 404
    data = request.get_json(force=True, silent=True) or {}
    new_status = data.get("status")
    actor = data.get("actor", "staff")
    if new_status not in VALID_STATUSES:
        return jsonify({"error": "Unknown order status"}), 400
    cur = order["status"]
    if new_status not in ALLOWED_TRANSITIONS.get(cur, set()):
        return jsonify({"error": f"Cannot change order from {cur} to {new_status}"}), 400
    if new_status == "fulfillment" and order.get("payment_status") != "paid":
        return jsonify({"error": "Unpaid order cannot move into fulfillment"}), 400
    before = dict(order)
    order["status"] = new_status
    audit("change_order_status", actor, before, dict(order))
    return jsonify(order)


@app.get("/audit")
def list_audit():
    return jsonify(state["audit"])


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8000)
EOF

