import unittest
from app import app, state

class StoreTests(unittest.TestCase):
    def setUp(self):
        state["catalog_ready"] = False
        state["products"].clear()
        state["orders"].clear()
        state["audit"].clear()
        state["carts"].clear()
        self.client = app.test_client()

    def test_catalog_must_be_ready_before_purchase(self):
        r = self.client.post("/admin/products", json={"name": "Widget", "price": 10, "stock": 5})
        pid = r.get_json()["id"]
        self.client.post("/admin/catalog/ready", json={"ready": True})
        r = self.client.post("/cart/c1/items", json={"product_id": pid, "quantity": 1})
        self.assertEqual(r.status_code, 200)

    def test_inactive_product_blocked(self):
        self.client.post("/admin/catalog/ready", json={"ready": True})
        r = self.client.post("/admin/products", json={"name": "Widget", "price": 10, "stock": 5, "active": False})
        pid = r.get_json()["id"]
        r = self.client.post("/cart/c1/items", json={"product_id": pid, "quantity": 1})
        self.assertEqual(r.status_code, 400)

    def test_checkout_and_payment(self):
        self.client.post("/admin/catalog/ready", json={"ready": True})
        pid = self.client.post("/admin/products", json={"name": "Widget", "price": 10, "stock": 5}).get_json()["id"]
        self.client.post("/cart/c1/items", json={"product_id": pid, "quantity": 2})
        order = self.client.post("/checkout/c1", json={"shipping_address": {"street": "1 Main", "city": "X", "postal_code": "123", "country": "US"}}).get_json()
        self.assertEqual(order["status"], "pending")
        pay = self.client.post(f"/orders/{order['id']}/pay", json={"payment_method": "trusted_provider"}).get_json()
        self.assertEqual(pay["status"], "success")
        got = self.client.get(f"/orders/{order['id']}").get_json()
        self.assertEqual(got["status"], "approved")
        self.assertEqual(got["payment_status"], "paid")

    def test_invalid_status_transition_blocked(self):
        self.client.post("/admin/catalog/ready", json={"ready": True})
        pid = self.client.post("/admin/products", json={"name": "Widget", "price": 10, "stock": 5}).get_json()["id"]
        self.client.post("/cart/c1/items", json={"product_id": pid, "quantity": 1})
        order = self.client.post("/checkout/c1", json={"shipping_address": {"street": "1 Main", "city": "X", "postal_code": "123", "country": "US"}}).get_json()
        r = self.client.post(f"/orders/{order['id']}/status", json={"status": "fulfillment"})
        self.assertEqual(r.status_code, 400)

if __name__ == "__main__":
    unittest.main()
EOF

